43	/// The state of an interrupted run's recovery record (`$script:PendingStates`).
44	#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
45	#[serde(rename_all = "lowercase")]
46	pub enum PendingState {
47	    Reserved,
48	    Launching,
49	    Running,
50	    Survivors,
51	    Committing,
52	}
53	
54	/// The informational content of `.consult.lock` / `.consult.write.lock`. Written compact
55	/// (one line) plus a trailing `\n`; nothing recoverable lives here.
56	#[derive(Debug, Clone, Serialize, Deserialize)]
57	pub struct LockRecord {
58	    pub pid: u32,
59	    /// The process start time as an ISO string (used with `pid` to tell a stale lock's
60	    /// owner from a live one).
61	    pub start_time: String,
62	    pub host: String,
63	    pub task: String,
64	    pub started: String,
65	    /// Present only for a panel run.
66	    #[serde(skip_serializing_if = "Option::is_none", default)]
67	    pub panel: Option<Value>,
68	}
69	
70	impl LockRecord {
71	    /// The compact, newline-terminated bytes the bridge writes into a lock file.
72	    pub fn to_bytes(&self) -> Result<Vec<u8>, serde_json::Error> {
73	        let mut s = serde_json::to_string(self)?;
74	        s.push('\n');
75	        Ok(s.into_bytes())
76	    }
