93	    pub launcher: String,
94	    pub engine: String,
95	    pub child_pid: Option<u32>,
96	    pub child_start_time: String,
97	    /// `{pid, start_time, name}` entries the kill could see; kept raw.
98	    pub survivors: Vec<Value>,
99	    pub note: String,
100	    /// Present only for a panel member's record.
101	    #[serde(skip_serializing_if = "Option::is_none", default)]
102	    pub panel: Option<Value>,
