209	/// Atomic replace: write to a temp file in the same directory, flush, rename over `path`.
210	/// `std::fs::rename` replaces an existing destination on both Windows and Unix. Mirrors
211	/// `Write-TextAtomic`.
212	pub fn write_text_atomic(path: &Path, bytes: &[u8]) -> io::Result<()> {
213	    let dir = path.parent().unwrap_or_else(|| Path::new("."));
214	    let name = path.file_name().and_then(|n| n.to_str()).unwrap_or("store");
215	    let tmp = dir.join(format!(".{name}.{}.tmp", uuid_like()));
216	    {
217	        let mut f = OpenOptions::new().write(true).create_new(true).open(&tmp)?;
218	        f.write_all(bytes)?;
219	        f.flush()?;
220	        f.sync_all()?;
221	    }
222	    fs::rename(&tmp, path)
223	}
224	
225	/// A cheap unique-ish suffix for temp file names (not a real UUID; only needs to avoid a
226	/// collision with a concurrent writer in the same directory).
227	fn uuid_like() -> String {
228	    use std::time::{SystemTime, UNIX_EPOCH};
229	    let nanos = SystemTime::now()
230	        .duration_since(UNIX_EPOCH)
231	        .map(|d| d.as_nanos())
232	        .unwrap_or(0);
233	    format!("{nanos:x}{:x}", std::process::id())
234	}
235	
236	fn read_opt(path: &Path) -> io::Result<Option<Vec<u8>>> {
237	    match fs::read(path) {
238	        Ok(b) => Ok(Some(b)),
239	        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(None),
240	        Err(e) => Err(e),
241	    }
242	}
243	
244	fn map_err(e: serde_json::Error) -> io::Error {
245	    io::Error::new(io::ErrorKind::InvalidData, e)
246	}
247	
248	impl EvidenceStore for FilesStore {
249	    fn task_dir(&self, task: &str) -> PathBuf {
250	        self.collab.join(task)
251	    }
252	
253	    fn read_sessions(&self, task: &str) -> io::Result<Option<SessionsFile>> {
254	        match read_opt(&self.task_dir(task).join("sessions.json"))? {
255	            Some(b) => Ok(Some(SessionsFile::read(&b).map_err(map_err)?)),
256	            None => Ok(None),
257	        }
258	    }
259	
260	    fn read_findings(&self, task: &str) -> io::Result<Option<FindingsFile>> {
261	        match read_opt(&self.task_dir(task).join("findings.json"))? {
262	            Some(b) => Ok(Some(FindingsFile::read(&b).map_err(map_err)?)),
263	            None => Ok(None),
264	        }
265	    }
266	
267	    fn recover_pending(&self, task: &str) -> io::Result<Vec<PendingRecord>> {
268	        let dir = self.task_dir(task);
269	        let mut single: Option<PendingRecord> = None;
270	        let mut members: Vec<(String, PendingRecord)> = Vec::new();
271	        let entries = match fs::read_dir(&dir) {
272	            Ok(e) => e,
273	            Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
274	            Err(e) => return Err(e),
275	        };
276	        for ent in entries {
277	            let ent = ent?;
278	            let name = ent.file_name().to_string_lossy().to_string();
279	            let is_single = name.eq_ignore_ascii_case(PENDING);
280	            let is_member = name.starts_with(".consult.pending-") && name.ends_with(".json");
281	            if !is_single && !is_member {
282	                continue;
283	            }
284	            let bytes = fs::read(ent.path())?;
285	            let rec: PendingRecord = serde_json::from_slice(&bytes).map_err(map_err)?;
286	            if is_single {
287	                single = Some(rec);
288	            } else {
289	                members.push((name, rec));
290	            }
291	        }
292	        members.sort_by_key(|(name, _)| name.to_lowercase());
293	        let mut out = Vec::new();
294	        if let Some(s) = single {
295	            out.push(s);
296	        }
297	        out.extend(members.into_iter().map(|(_, r)| r));
298	        Ok(out)
299	    }
300	
301	    fn next_handoff_number(&self, task: &str) -> io::Result<u32> {
302	        let dir = self.task_dir(task);
303	        let mut max_nn: u32 = 0;
304	        // handoff files "<NN>-..." (two or more digits).
305	        if let Ok(entries) = fs::read_dir(dir.join("handoffs")) {
306	            for ent in entries.flatten() {
307	                let name = ent.file_name().to_string_lossy().to_string();
308	                if let Some(nn) = leading_number(&name) {
309	                    max_nn = max_nn.max(nn);
310	                }
311	            }
312	        }
313	        // finding ids F<NN>-<k>.
314	        if let Some(f) = self.read_findings(task)? {
315	            for fd in &f.findings {
316	                if let Some(nn) = finding_nn(&fd.id) {
317	                    max_nn = max_nn.max(nn);
318	                }
319	            }
320	        }
321	        // recovery records' nn.
322	        for rec in self.recover_pending(task)? {
323	            if let Ok(nn) = rec.nn.parse::<u32>() {
324	                max_nn = max_nn.max(nn);
325	            }
326	        }
327	        Ok(max_nn + 1)
328	    }
