330	    fn take_task_lock(&self, task: &str, record: &LockRecord) -> io::Result<TaskLock> {
331	        let dir = self.task_dir(task);
332	        fs::create_dir_all(&dir)?;
333	        let path = dir.join(OWNERSHIP_LOCK);
334	        // Open (create if absent) and hold the handle. NOTE (M3): the bridge opens with
335	        // FileShare.Read on Windows / FileShare.None on Unix so a second run's exclusive
336	        // open fails fast; reproducing that exact share mode needs a platform open call.
337	        // Here we hold the handle open, which is the contract; the share flags are M3.
338	        let mut file = OpenOptions::new()
339	            .read(true)
340	            .write(true)
341	            .create(true)
342	            .truncate(false)
343	            .open(&path)?;
344	        let bytes = record.to_bytes().map_err(map_err)?;
345	        file.set_len(0)?;
346	        file.write_all(&bytes)?;
347	        file.flush()?;
348	        Ok(TaskLock { path, _file: file })
349	    }
350	
351	    fn write_pending(&self, task: &str, record: &PendingRecord) -> io::Result<()> {
352	        let dir = self.task_dir(task);
353	        fs::create_dir_all(&dir)?;
354	        let path = dir.join(PENDING);
355	        write_text_atomic(&path, &record.to_bytes().map_err(map_err)?)
356	    }
357	
358	    fn commit(
359	        &self,
360	        task: &str,
361	        entry: LedgerEntry,
362	        findings: Option<FindingsFile>,
363	        files: &[(PathBuf, Vec<u8>)],
364	    ) -> io::Result<u64> {
365	        let dir = self.task_dir(task);
366	        fs::create_dir_all(&dir)?;
367	        // (In a full runtime this holds .consult.write.lock across the whole sequence and
368	        // returns commit_wait_ms; here the lock acquisition/backoff is M3 - see
369	        // take_task_lock's note - and the ordered writes below ARE the encoded write order.)
370	        // ReReadStores: start from the fresh on-disk ledger, apply this run's delta.
371	        let mut sessions = self.read_sessions(task)?.unwrap_or_else(|| SessionsFile {
372	            task_id: task.to_string(),
373	            cwd: String::new(),
374	            codex: crate::ledger::LedgerBook {
375	                tool: entry.reviewer.harness.clone(),
376	                consults: Vec::new(),
377	            },
378	        });
379	        sessions.add_entry(entry);
380	        // HandoffMarkdown (and any other per-consultation files).
381	        for (rel, bytes) in files {
382	            let path = dir.join(rel);
383	            if let Some(parent) = path.parent() {
384	                fs::create_dir_all(parent)?;
385	            }
386	            write_text_atomic(&path, bytes)?;
387	        }
388	        // Findings, then Sessions (the commit point).
389	        if let Some(f) = findings {
390	            write_text_atomic(&dir.join("findings.json"), &f.to_bytes().map_err(map_err)?)?;
391	        }
392	        write_text_atomic(
393	            &dir.join("sessions.json"),
394	            &sessions.to_bytes().map_err(map_err)?,
395	        )?;
396	        // RemoveRecoveryRecord.
397	        let pending = dir.join(PENDING);
398	        if pending.exists() {
399	            fs::remove_file(&pending)?;
400	        }
401	        Ok(0)
402	    }
403	}
