267	    fn recover_pending(&self, task: &str) -> io::Result<Vec<PendingRecord>> {
268	        let dir = self.task_dir(task);
269	        let mut single: Option<PendingRecord> = None;
270	        let mut members: Vec<(String, PendingRecord)> = Vec::new();
271	        let entries = match fs::read_dir(&dir) {
272	            Ok(e) => e,
273	            Err(e) if e.kind() == io::ErrorKind::NotFound => return Ok(Vec::new()),
274	            Err(e) => return Err(e),
275	        };
276	        for ent in entries {
277	            let ent = ent?;
278	            let name = ent.file_name().to_string_lossy().to_string();
279	            let is_single = name.eq_ignore_ascii_case(PENDING);
280	            let is_member = name.starts_with(".consult.pending-") && name.ends_with(".json");
281	            if !is_single && !is_member {
282	                continue;
283	            }
284	            let bytes = fs::read(ent.path())?;
285	            let rec: PendingRecord = serde_json::from_slice(&bytes).map_err(map_err)?;
286	            if is_single {
287	                single = Some(rec);
288	            } else {
289	                members.push((name, rec));
290	            }
291	        }
292	        members.sort_by_key(|(name, _)| name.to_lowercase());
293	        let mut out = Vec::new();
294	        if let Some(s) = single {
295	            out.push(s);
296	        }
297	        out.extend(members.into_iter().map(|(_, r)| r));
298	        Ok(out)
299	    }
