304	        // handoff files "<NN>-..." (two or more digits).
305	        if let Ok(entries) = fs::read_dir(dir.join("handoffs")) {
306	            for ent in entries.flatten() {
307	                let name = ent.file_name().to_string_lossy().to_string();
308	                if let Some(nn) = leading_number(&name) {
309	                    max_nn = max_nn.max(nn);
310	                }
311	            }
312	        }
313	        // finding ids F<NN>-<k>.
314	        if let Some(f) = self.read_findings(task)? {
315	            for fd in &f.findings {
316	                if let Some(nn) = finding_nn(&fd.id) {
317	                    max_nn = max_nn.max(nn);
318	                }
319	            }
320	        }
321	        // recovery records' nn.
322	        for rec in self.recover_pending(task)? {
323	            if let Ok(nn) = rec.nn.parse::<u32>() {
324	                max_nn = max_nn.max(nn);
325	            }
326	        }
327	        Ok(max_nn + 1)
328	    }
