1	//! Windows PowerShell 5.1 `ConvertTo-Json` output, reproduced byte-for-byte.
2	//!
3	//! The bridge writes every JSON store with `Write-JsonFile`
4	//! (`codex-consult-common.ps1`): `ConvertTo-Json -InputObject $o -Depth 20`, then a
5	//! CRLF->LF pass and one trailing `\n`. On the reference machine that `ConvertTo-Json`
6	//! is Windows PowerShell 5.1's, backed by `System.Web.Script.Serialization.
7	//! JavaScriptSerializer` and 5.1's indenter. That combination has three signatures this
8	//! module reproduces exactly, verified against the real `.collab/c3-design/sessions.json`
9	//! and `findings.json`:
10	//!
11	//! 1. **Column-anchored indentation.** The value of a key is written on the key's own
12	//!    line, right after `"<key>":  ` (colon, then TWO spaces). A container's members are
13	//!    indented four columns past the *column of its opening bracket* - not four per depth
14	//!    level. So `bracket_col = key_indent + quoted_key.len() + 3` (`+1` colon, `+2`
15	//!    spaces), members sit at `bracket_col + 4`, and the closing bracket sits back at
16	//!    `bracket_col`. An empty array is `[`, a blank line, then `]` at the bracket column.
17	//! 2. **Escaping (JavaScriptSerializer).** Only `"` and `\` take short escapes; `<`, `>`,
18	//!    `&` and `'` are escaped as `<`, `>`, `&`, `'`; control
19	//!    characters (`< 0x20`) and `U+2028`/`U+2029` as `\uXXXX` (lowercase). Every other
20	//!    character, including all non-ASCII, is written raw as UTF-8.
21	//! 3. **.NET number text.** A whole-valued double is written without a decimal point
22	//!    (`277`, not `277.0`), because the bridge rounds wall times to a `[double]` and
23	//!    `ConvertTo-Json` prints `277.0` as `277`; a fractional double keeps its shortest
24	//!    round-trip form (`243.4`). Integers print as-is.
25	//!
26	//! The one host-dependent caveat: run under PowerShell 7 the same `Write-JsonFile`
27	//! produces DIFFERENT bytes (single space after the colon, plain per-level indentation).
28	//! C3 therefore canonicalises to the 5.1 shape - the shape of the evidence on disk - and
29	//! the byte-identity acceptance test in `tests/formats.rs` pins it. See
30	//! `docs/port/contracts.md` for the review question this raises.
31	
32	use serde::Serialize;
33	use serde_json::Value;
34	
35	/// Serialize `value` to the PowerShell-5.1 `ConvertTo-Json` text (no trailing newline).
36	pub fn to_ps_json<T: Serialize>(value: &T) -> Result<String, serde_json::Error> {
37	    let v = serde_json::to_value(value)?;
38	    Ok(format_value_root(&v))
39	}
40	
41	/// Serialize `value` exactly as `Write-JsonFile` writes a store: the PowerShell-5.1 text,
42	/// LF line endings, plus the one trailing `\n`. This is the on-disk byte stream.
43	pub fn to_ps_json_bytes<T: Serialize>(value: &T) -> Result<Vec<u8>, serde_json::Error> {
44	    let mut s = to_ps_json(value)?;
45	    s.push('\n');
46	    Ok(s.into_bytes())
47	}
48	
49	/// Format a parsed [`Value`] as the PowerShell-5.1 text (no trailing newline). Used by the
50	/// formatter's own tests to prove byte-identity independently of any typed struct.
51	pub fn format_value_root(value: &Value) -> String {
52	    let mut out = String::new();
53	    write_value(&mut out, value, 0);
54	    out
