137	/// Quote and escape a string the way JavaScriptSerializer does.
138	fn escape_json_string(s: &str) -> String {
139	    let mut out = String::with_capacity(s.len() + 2);
140	    out.push('"');
141	    for c in s.chars() {
142	        match c {
143	            '"' => out.push_str("\\\""),
144	            '\\' => out.push_str("\\\\"),
145	            '<' => out.push_str("\\u003c"),
146	            '>' => out.push_str("\\u003e"),
147	            '&' => out.push_str("\\u0026"),
148	            '\'' => out.push_str("\\u0027"),
149	            '\u{2028}' => out.push_str("\\u2028"),
150	            '\u{2029}' => out.push_str("\\u2029"),
151	            c if (c as u32) < 0x20 => {
152	                out.push_str(&format!("\\u{:04x}", c as u32));
153	            }
154	            c => out.push(c),
155	        }
156	    }
157	    out.push('"');
158	    out
159	}
